    'targets.json':{desc:'Two independent targets with explicit retry budgets and Standard delivery DLQ',content:JSON.stringify(targets,null,2)},
    'schedule-target.json':{desc:'Scheduler execution-role path with retry and delivery DLQ',content:JSON.stringify(scheduleTarget,null,2)},
    'refund-flow.asl.json':{desc:'Bounded real ASL shape with TEST worker Tasks, OutOfStock Catch and refund retry',content:JSON.stringify(definition,null,2)},
    'event-entries.json':{desc:'PutEvents Detail is JSON string; acceptance differs from delivery',content:JSON.stringify([{Source:'shop.orders',DetailType:'RefundRequested',Detail:JSON.stringify(detail)}],null,2)},
    'refund-input.json':{desc:'Original stable order identity for TEST compensation path',content:JSON.stringify(input,null,2)},
